const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
const clean = raw.replace(/```json|```/g, '').trim();
const match = clean.match(/\{[\s\S]*\}/);
let a = {};
try { a = JSON.parse(match?.[0] || '{}'); } catch(_) {}

const input = $('Execute Workflow Trigger').first().json;
let niche = '';
try {
  const report = input.trendReport ? JSON.parse(input.trendReport) : input;
  niche = report.niche || '';
} catch(_) { niche = input.niche || ''; }

return [{ json: { niche, ...a } }];

